package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.phys.Vec3;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class GlidePlatformLayoutTest {
 @Test void renderClockRetainsFractionalTicksInOldWorlds(){long end=1L<<42;assertEquals(.5625F,GlidePlatformLayout.renderBlend(end+4,end,.5F),1e-7);assertEquals(0,GlidePlatformLayout.renderBlend(end-1,end,0));assertEquals(1,GlidePlatformLayout.renderBlend(end+8,end,0));}
 @Test void originalEighteenPartIndicesStillResolveToTheirSavedAnchor(){for(Direction d:new Direction[]{Direction.SOUTH,Direction.WEST,Direction.NORTH,Direction.EAST}){var origin=new BlockPos(-18,80,47);var parts=new HashSet<BlockPos>();int old=0;for(int y=0;y<2;y++)for(int z:new int[]{0,-1,1})for(int x=0;x<3;x++){assertEquals(origin.relative(GlidePlatformLayout.right(d),x).relative(d,z).above(y),GlidePlatformLayout.cell(origin,d,old++));}for(int i=0;i<GlidePlatformLayout.PARTS;i++){var p=GlidePlatformLayout.cell(origin,d,i);assertTrue(parts.add(p));assertEquals(origin,GlidePlatformLayout.anchor(p,d,i));}assertTrue(parts.size()>18);}}
 @Test void nativeFullSizeHalfTurnAndNineUnitLiftAreAppliedOnce(){assertEquals(1,GlidePlatformLayout.FIT_SCALE);assertEquals(0,GlidePlatformLayout.MOUNT_PITCH);assertEquals(0,new Vec3(0,9/16D,0).distanceTo(GlidePlatformLayout.fitPoint(Vec3.ZERO)),1e-12);assertEquals(new Vec3(-1,25/16D,2),GlidePlatformLayout.fitPoint(new Vec3(16,16,-32)));assertEquals(.55,GlidePlatformLayout.LAUNCH_SPEED);assertEquals(Math.tan(Math.toRadians(8))*.55,GlidePlatformLayout.LAUNCH_RISE,1e-10);}
 @Test void suppliedPositionAndRotationChannelsUseTheirOwnAxes(){assertEquals(18,GlidePlatformClampAnimation.TICKS);assertEquals(9,GlidePlatformClampAnimation.LID_TICKS);assertEquals(0,GlidePlatformClampAnimation.position("clamp_left",0,5/18F),1e-5);assertEquals(-24,GlidePlatformClampAnimation.position("clamp_left",0,1),1e-5);assertEquals(24,GlidePlatformClampAnimation.position("clamp_right",0,1),1e-5);assertEquals(0,GlidePlatformClampAnimation.rotation("clamp_left",2,1));assertEquals(Math.PI/2,GlidePlatformClampAnimation.rotation("gate_left",1,1),1e-6);assertEquals(-Math.PI/2,GlidePlatformClampAnimation.rotation("gate_right",1,1),1e-6);assertEquals(Math.toRadians(100),GlidePlatformClampAnimation.cover(1),1e-6);}
 @Test void frameShapesAreCachedCellLocalAndKeepTheCentralWalkingSpaceOpen(){for(Direction d:new Direction[]{Direction.SOUTH,Direction.WEST,Direction.NORTH,Direction.EAST})for(int i=0;i<GlidePlatformLayout.PARTS;i++){int[] n={0};GlidePlatformShapes.selection(d,i).forAllEdges((a,b,c,x,y,z)->n[0]++);assertTrue(n[0]<=12);var shape=GlidePlatformShapes.collision(d,i);if(!shape.isEmpty()){var b=shape.bounds();assertTrue(b.minX>=-1e-6&&b.minY>=0&&b.minZ>=-1e-6&&b.maxX<=1.000001&&b.maxY<=1&&b.maxZ<=1.000001);}int[] cell=GlidePlatformLayout.CELLS[i];double x=1.5-cell[0],y=1.3-cell[2],z=.5-cell[1];if(d==Direction.SOUTH)assertFalse(shape.toAabbs().stream().anyMatch(b->b.contains(new Vec3(x,y,z))),"solid cube through the suspended centre");}}
 @Test void fullPayloadBoundsMatchTheFitSceneAndPlacementExcludesTheFloor(){var p=BlockPos.ZERO;var b=GlidePlatformLayout.droneBounds(p,Direction.SOUTH);assertEquals(45/16D+.05,b.getXsize(),1e-8);assertEquals(24.5/16D+.05,b.getYsize(),1e-8);assertEquals(9/16D-.025,b.minY,1e-8);assertTrue(GlidePlatformLayout.openingBounds(p,Direction.SOUTH).minY>0);assertTrue(GlidePlatformLayout.openingBounds(p,Direction.SOUTH).maxY>2.6);}
}
